import{_ as e,c as t,o as n,a as o}from"./app.19f3f8f0.js";const y=JSON.parse('{"title":"Connect your Instagram to ReplyBridge","description":"Link your Instagram Business or Creator account to ReplyBridge—explained in simple steps for non-technical users.","frontmatter":{"title":"Connect your Instagram to ReplyBridge","description":"Link your Instagram Business or Creator account to ReplyBridge—explained in simple steps for non-technical users."},"headers":[{"level":2,"title":"What you need","slug":"what-you-need","link":"#what-you-need","children":[]},{"level":2,"title":"What happens when you tap “Connect”","slug":"what-happens-when-you-tap-connect","link":"#what-happens-when-you-tap-connect","children":[]},{"level":2,"title":"If something goes wrong","slug":"if-something-goes-wrong","link":"#if-something-goes-wrong","children":[]},{"level":2,"title":"Next step","slug":"next-step","link":"#next-step","children":[]}],"relativePath":"replybridge/integration.md"}'),r={name:"replybridge/integration.md"},a=o('<h1 id="connect-your-instagram" tabindex="-1">Connect your Instagram <a class="header-anchor" href="#connect-your-instagram" aria-hidden="true">#</a></h1><p>You only need to do this <strong>once</strong> (or again if Instagram asks you to reconnect). You <strong>do not</strong> need to be a developer or build your own Instagram app—ReplyBridge handles the technical side.</p><p><strong>New to ReplyBridge?</strong> Start with <strong><a href="/replybridge/getting-started">Get started — install &amp; set up</a></strong> first.</p><hr><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-hidden="true">#</a></h2><table><thead><tr><th>Requirement</th><th>Why</th></tr></thead><tbody><tr><td><strong>Business or Creator account</strong></td><td>Instagram only allows this kind of automation for these account types.</td></tr><tr><td><strong>Facebook Page link (when required)</strong></td><td>Instagram often connects through a Facebook Page. The ReplyBridge app will tell you if something is missing.</td></tr></tbody></table><hr><h2 id="what-happens-when-you-tap-connect" tabindex="-1">What happens when you tap “Connect” <a class="header-anchor" href="#what-happens-when-you-tap-connect" aria-hidden="true">#</a></h2><ol><li>You stay inside <strong>ReplyBridge</strong> until it opens a <strong>browser window</strong> (usually Safari).</li><li>You <strong>log in</strong> to Facebook/Instagram and <strong>allow</strong> the permissions the app asks for. These let ReplyBridge read comments on your posts and send the messages <strong>you</strong> configure.</li><li>You return to ReplyBridge and should see <strong>Connected</strong> or similar.</li></ol><p>If any step fails, check your internet, update the Instagram and Facebook apps, and try <strong>Connect</strong> again.</p><hr><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-hidden="true">#</a></h2><table><thead><tr><th>Problem</th><th>What to try</th></tr></thead><tbody><tr><td>“Can’t connect” or login loops</td><td>Close the browser tab, reopen ReplyBridge, tap Connect again.</td></tr><tr><td>Permissions denied</td><td>In phone settings, allow the browser to complete login; then retry in the app.</td></tr><tr><td>Instagram disconnected</td><td>Open the Instagram app and confirm your account and Page are still linked; reconnect in ReplyBridge.</td></tr><tr><td>Token expired</td><td>Use <strong>Reconnect</strong> or <strong>Connect again</strong> inside ReplyBridge.</td></tr></tbody></table><p>Still stuck? Use <a href="/contact">Contact</a> with your Instagram handle and a screenshot if possible.</p><hr><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-hidden="true">#</a></h2><p>Set up your first automated message: <strong><a href="/replybridge/getting-started">Get started</a></strong> or <strong><a href="/replybridge/usage">How to use</a></strong>.</p>',17),s=[a];function i(d,h,g,l,p,c){return n(),t("div",null,s)}const m=e(r,[["render",i]]);export{y as __pageData,m as default};
